// ==========================================
// USER SETTINGS
// ==========================================

// Battery bank
const BATTERY_WH = 2400;

// Typical overnight draw
const NIGHT_LOAD_W = 200;

// Inverter protection
const HARD_LOAD_LIMIT = 1200;
const HIGH_LOAD_LIMIT = 900;

// Solar requirements
const REQUIRED_SOLAR_MARGIN = 300;

// Battery protection
const LOW_VOLTAGE_LIMIT = 23.8;

// Require battery charging or nearly neutral
const BATTERY_POWER_THRESHOLD = 0;

// Sunset reserve
const SUNSET_SOC_THRESHOLD = 30;

// Sunrise fallback
const SUNRISE_FALLBACK_HOURS = 16;

// ==========================================
// STATE VARIABLES
// ==========================================

let currentMode =
    context.get("currentMode") || 0;

let soc =
    context.get("soc") || 100;

let voltage =
    context.get("voltage") || 26.4;

let acLoad =
    context.get("acLoad") || 0;

let batteryPower =
    context.get("batteryPower") || 0;

let manualOverride =
    context.get("manualOverride") || 0;

let solarWatts1 =
    context.get("solarWatts1") || 0;

let solarWatts2 =
    context.get("solarWatts2") || 0;

// ==========================================
// INPUT PROCESSING
// ==========================================

if (msg.topic) {

    let topic =
        msg.topic.toLowerCase();

    if (topic.includes("soc")) {

        soc = Number(msg.payload);

        context.set(
            "soc",
            soc
        );
    }

    if (topic.includes("voltage")) {

        voltage =
            Number(msg.payload);

        context.set(
            "voltage",
            voltage
        );
    }

    if (
        topic.includes("ac/out/l1/p") ||
        topic.includes("ac/acout/l1/p") ||
        topic.includes("consumption")
    ) {

        acLoad =
            Number(msg.payload);

        context.set(
            "acLoad",
            acLoad
        );
    }

    if (
        topic.includes("dc/0/power")
    ) {

        batteryPower =
            Number(msg.payload);

        context.set(
            "batteryPower",
            batteryPower
        );
    }

    if (
        topic.includes("solarcharger")
    ) {

        if (
            topic.includes("/0/") ||
            topic.includes("instance0")
        ) {

            solarWatts1 =
                Number(msg.payload);

            context.set(
                "solarWatts1",
                solarWatts1
            );

        } else {

            solarWatts2 =
                Number(msg.payload);

            context.set(
                "solarWatts2",
                solarWatts2
            );
        }
    }
}

// ==========================================
// MANUAL OVERRIDE
// ==========================================

if (!msg.topic) {

    if (
        msg.payload === true ||
        msg.payload === 1 ||
        msg.payload === 101
    ) {

        manualOverride = 1;

    } else {

        manualOverride = 0;
    }

    context.set(
        "manualOverride",
        manualOverride
    );
}

// ==========================================
// LIVE SYSTEM TOTALS
// ==========================================

let totalSolar =
    solarWatts1 +
    solarWatts2;

let solarMargin =
    totalSolar -
    acLoad;

// ==========================================
// WEATHER VARIABLES
// ==========================================

let dynamicFloor =
    global.get(
        "dynamicLowerSoC"
    ) || 20;

let forecastClouds =
    global.get(
        "forecastClouds"
    ) || 0;

let forecastRain =
    global.get(
        "forecastRain"
    ) || false;

let severeWeather =
    global.get(
        "severeWeather"
    ) || false;

let sunriseTime =
    global.get(
        "actualSunriseTime"
    ) || 0;

let sunsetTime =
    global.get(
        "actualSunsetTime"
    ) || 0;

// ==========================================
// ENERGY PLANNING
// ==========================================

let now = Date.now();

let nextSunrise =
    sunriseTime;

// if today's sunrise has already passed
// estimate tomorrow morning

if (
    nextSunrise <= now ||
    nextSunrise === 0
) {

    nextSunrise =
        now +
        (
            SUNRISE_FALLBACK_HOURS *
            3600000
        );
}

let hoursToSunrise =
    (
        nextSunrise -
        now
    ) / 3600000;

let usableWh =
    BATTERY_WH *
    Math.max(
        0,
        (
            soc - 20
        ) / 100
    );

let overnightNeedWh =
    NIGHT_LOAD_W *
    hoursToSunrise;

let reserveRequired =
    overnightNeedWh * 1.20;

let hoursToSunset = 99;

if (
    sunsetTime > now
) {

    hoursToSunset =
        (
            sunsetTime -
            now
        ) / 3600000;
}

// ==========================================
// DECISION ENGINE
// ==========================================

let targetMode =
    currentMode;

/*
0 = Shore/Grid

1 = Solar
*/

// Manual override

if (
    manualOverride === 1
) {

    targetMode = 0;

}

// Severe weather reserve mode

else if (
    severeWeather
) {

    targetMode = 0;

}

// Inverter protection

else if (
    acLoad >= HARD_LOAD_LIMIT
) {

    targetMode = 0;

}

// Heavy loads without enough solar

else if (
    acLoad >= HIGH_LOAD_LIMIT &&
    totalSolar <
        (
            acLoad +
            REQUIRED_SOLAR_MARGIN
        )
) {

    targetMode = 0;

}

// Battery reserve reached

else if (
    soc <= dynamicFloor
) {

    targetMode = 0;

}

// Voltage emergency

else if (
    voltage <= LOW_VOLTAGE_LIMIT
) {

    targetMode = 0;

}

// Cannot survive until sunrise

else if (
    usableWh <
    reserveRequired
) {

    targetMode = 0;

}

// Rain forecast

else if (
    forecastRain &&
    soc < (dynamicFloor + 5)
) {

    targetMode = 0;

}

// Severe weather

else if (
    severeWeather
) {

    targetMode = 0;

}

// Near sunset

else if (
    hoursToSunset < 2 &&
    soc < SUNSET_SOC_THRESHOLD
) {

    targetMode = 0;

}

// Very poor solar outlook

else if (
    forecastClouds > 85 &&
    soc < 60
) {

    targetMode = 0;

}

// Solar mode allowed

else if (

    solarMargin >
        REQUIRED_SOLAR_MARGIN &&

    soc >
        (
            dynamicFloor +
            5
        ) &&

    forecastClouds < 75 &&

    batteryPower >
        BATTERY_POWER_THRESHOLD

) {

    targetMode = 1;

}

// Hold previous state

else {

    targetMode =
        currentMode;
}

// ==========================================
// OUTPUT GATE
// ==========================================

let lastSentPayload =
    context.get(
        "lastSentPayload"
    );

let outputPayload =
    (
        targetMode === 0
    )
        ? 1
        : 0;

if (
    outputPayload ===
    lastSentPayload
) {

    return [
        null,
        null,
        null
    ];
}

context.set(
    "lastSentPayload",
    outputPayload
);

context.set(
    "currentMode",
    targetMode
);

// ==========================================
// STATUS
// ==========================================

node.status({

    fill:
        targetMode === 1
            ? "green"
            : "yellow",

    shape: "dot",

    text:
        "SOC " +
        soc.toFixed(0) +
        "% PV " +
        totalSolar +
        "W Load " +
        acLoad +
        "W Batt " +
        batteryPower +
        "W Floor " +
        dynamicFloor +
        "%" +
        (
            severeWeather
                ? " STORM"
                : ""
        )
});

// ==========================================
// OUTPUTS
// ==========================================

let msgMode = {

    payload:
        outputPayload,

    topic:
        "Force Shore Control"
};

let msgAlarm = {

    payload:
        outputPayload === 1
            ? 1
            : 0
};

return [
    msgMode,
    msgAlarm,
    null
];

// Initialize local tracking variables
let lowBatteryAlarm = msg.payload; 
let faultState = 0;
let statusMessage = "System Status Normal";
let statusColor = "green";

// Evaluate the incoming Victron Low Battery Alarm binary state
if (lowBatteryAlarm === 1 || lowBatteryAlarm === true) {
    faultState = 1;
    statusMessage = "WARNING: Battery Voltage Sagging Under Load!";
    statusColor = "red";
} else {
    faultState = 0;
    statusMessage = "System Status Normal";
    statusColor = "green";
}

// Display the text beautifully right under the node box on your workspace canvas
node.status({ fill: statusColor, shape: "dot", text: statusMessage });

// Send ONLY a clean raw number down the wire to the rigid Victron hardware node
msg.payload = faultState;
return msg;

// ==========================================
// USER SETTINGS
// ==========================================

// Base battery reserve
const SUNNY_FLOOR = 20;

// Weather reserve floors
const PARTLY_CLOUDY_FLOOR = 40;
const CLOUDY_FLOOR = 50;
const VERY_CLOUDY_FLOOR = 60;
const RAIN_FLOOR = 70;
const EXTENDED_BAD_WEATHER_FLOOR = 85;

// Cloud thresholds
const PARTLY_CLOUDY_THRESHOLD = 35;
const CLOUDY_THRESHOLD = 65;
const VERY_CLOUDY_THRESHOLD = 85;

// Rain threshold
const RAIN_CHANCE_THRESHOLD = 50;

// Forecast periods to evaluate
// 8 periods = ~24 hours
const FORECAST_PERIODS = 8;

// Sunset protection
const SUNSET_BUFFER_HOURS = 4;
const SUNSET_CRITICAL_HOURS = 2;

// Severe weather reserve
const STORM_FLOOR = 100;

// Wind thresholds (mph)
const HIGH_WIND_MPH = 40;
const SEVERE_WIND_MPH = 55;

// Snow thresholds
const HEAVY_SNOW_INCHES = 4;

// Ice threshold
const ICE_THRESHOLD = 0.10;

// ==========================================
// START
// ==========================================

let forecast = msg.payload || [];

let worstClouds = 0;
let rainChance = 0;
let rainExpected = false;
let severeWeather = false;
let badPeriods = 0;
let stormReason = "";

// Sunrise/Sunset values supplied by
// current weather node

let sunriseTime =
    global.get("actualSunriseTime") || 0;

let sunsetTime =
    global.get("actualSunsetTime") || 0;

// ==========================================
// FORECAST ANALYSIS
// ==========================================

let sampleCount =
    Math.min(
        FORECAST_PERIODS,
        forecast.length
    );

for (let i = 0; i < sampleCount; i++) {

    let item = forecast[i];

    let clouds = 0;

    // ----------------------------------
    // CLOUD COVER
    // ----------------------------------

    if (
        item.clouds &&
        item.clouds.all !== undefined
    ) {

        clouds =
            Number(item.clouds.all);

        worstClouds = Math.max(
            worstClouds,
            clouds
        );
    }

    // ----------------------------------
    // RAIN CHANCE
    // ----------------------------------

    if (
        item.pop !== undefined
    ) {

        let thisPop =
            Number(item.pop) * 100;

        rainChance = Math.max(
            rainChance,
            thisPop
        );

        if (
            thisPop >=
            RAIN_CHANCE_THRESHOLD
        ) {

            badPeriods++;
        }
    }

    // ----------------------------------
    // VERY CLOUDY PERIODS
    // ----------------------------------

    if (
        clouds >=
        VERY_CLOUDY_THRESHOLD
    ) {

        badPeriods++;
    }

    // ----------------------------------
    // WEATHER CONDITIONS
    // ----------------------------------

    if (
        item.weather &&
        item.weather.length > 0
    ) {

        let condition =
            item.weather[0].main;

        let description =
            (
                item.weather[0].description || ""
            ).toLowerCase();

        if (
            condition === "Rain" ||
            condition === "Drizzle" ||
            condition === "Thunderstorm" ||
            condition === "Snow"
        ) {

            rainExpected = true;
        }

        // Severe Weather Detection

        if (
            description.includes("tornado") ||
            description.includes("hurricane") ||
            description.includes("blizzard") ||
            description.includes("ice") ||
            description.includes("ice storm") ||
            description.includes("freezing") ||
            description.includes("freezing rain") ||
            description.includes("heavy snow") ||
            description.includes("winter storm") ||
            description.includes("damaging wind") ||
            description.includes("high wind") ||
            description.includes("wind advisory") ||
            description.includes("wind warning") ||
            description.includes("severe") ||
            description.includes("strong thunderstorm") ||
            description.includes("violent storm")
        ) {

            severeWeather = true;
            stormReason = description;
        }

        if (
            condition === "Thunderstorm"
        ) {

            severeWeather = true;

            if (stormReason === "") {
                stormReason = "thunderstorm";
                }
            }
        }

    // ----------------------------------
    // WIND ANALYSIS
    // ----------------------------------

    if (
        item.wind &&
        item.wind.speed !== undefined
    ) {

        let windMph =
            Number(item.wind.speed) * 2.237;

        if (
            windMph >=
            HIGH_WIND_MPH
        ) {

            badPeriods++;
        }

        if (
            windMph >=
            SEVERE_WIND_MPH
        ) {

            severeWeather = true;

            if (stormReason === "") {

                stormReason =
                    "wind " +
                    Math.round(windMph) +
                    "mph";
            }
        }
    }
}

// ==========================================
// BASE FLOOR SELECTION
// ==========================================

let recommendedFloor =
    SUNNY_FLOOR;

if (
    severeWeather
) {

    recommendedFloor =
        STORM_FLOOR;

}
else if (
    rainExpected ||
    rainChance >=
    RAIN_CHANCE_THRESHOLD
) {

    recommendedFloor =
        RAIN_FLOOR;

}
else if (
    worstClouds >=
    VERY_CLOUDY_THRESHOLD
) {

    recommendedFloor =
        VERY_CLOUDY_FLOOR;

}
else if (
    worstClouds >=
    CLOUDY_THRESHOLD
) {

    recommendedFloor =
        CLOUDY_FLOOR;

}
else if (
    worstClouds >=
    PARTLY_CLOUDY_THRESHOLD
) {

    recommendedFloor =
        PARTLY_CLOUDY_FLOOR;

}

// ==========================================
// EXTENDED BAD WEATHER
// ==========================================

if (
    !severeWeather &&
    badPeriods >= 4
) {

    recommendedFloor =
        Math.max(
            recommendedFloor,
            EXTENDED_BAD_WEATHER_FLOOR
        );
}

// ==========================================
// SUNSET PROTECTION
// ==========================================

let now = Date.now();

let hoursToSunset = 99;

if (
    sunsetTime > now
) {

    hoursToSunset =
        (
            sunsetTime -
            now
        ) / 3600000;
}

if (
    !severeWeather &&
    hoursToSunset <
    SUNSET_BUFFER_HOURS
) {

    recommendedFloor =
        Math.max(
            recommendedFloor,
            CLOUDY_FLOOR
        );
}

if (
    !severeWeather &&
    hoursToSunset <
    SUNSET_CRITICAL_HOURS
) {

    recommendedFloor =
        Math.max(
            recommendedFloor,
            VERY_CLOUDY_FLOOR
        );
}

// ==========================================
// SAVE GLOBALS
// ==========================================

global.set(
    "dynamicLowerSoC",
    recommendedFloor
);

global.set(
    "forecastClouds",
    worstClouds
);

global.set(
    "forecastRain",
    rainExpected
);

global.set(
    "rainChance",
    rainChance
);

global.set(
    "severeWeather",
    severeWeather
);

global.set(
    "stormReason",
    stormReason
);

// ==========================================
// STATUS
// ==========================================

node.status({

    fill:
        severeWeather
            ? "red"
            : "blue",

    shape: "dot",

    text:
        severeWeather
            ? (
                "STORM | " +
                stormReason +
                " | Floor " +
                recommendedFloor +
                "%"
            )
            : (
                "Floor " +
                recommendedFloor +
                "% | Clouds " +
                worstClouds +
                "% | Rain " +
                Math.round(
                    rainChance
                ) +
                "%"
            )

});

return msg;

if (
    msg.payload &&
    msg.payload.sys
) {

    if (msg.payload.sys.sunrise) {

        global.set(
            "actualSunriseTime",
            msg.payload.sys.sunrise * 1000
        );
    }

    if (msg.payload.sys.sunset) {

        global.set(
            "actualSunsetTime",
            msg.payload.sys.sunset * 1000
        );
    }
}

return msg;
